-- Neural semantic embeddings generated locally with Sentence Transformers.
-- Model: sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2
-- Each vector has 384 dimensions and is L2-normalized.
-- Input text includes category, question, and answer; encode search queries with the same model.
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS public.qa (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category text NOT NULL,
    question text NOT NULL,
    answer text NOT NULL,
    embedding vector(384),
    created_at timestamptz NOT NULL DEFAULT now()
 );

-- Replace vectors generated by the prior embedding model.
DROP INDEX IF EXISTS public.qa_embedding_hnsw_idx;
ALTER TABLE public.qa DROP COLUMN IF EXISTS embedding;
ALTER TABLE public.qa ADD COLUMN embedding vector(384);

ON CONFLICT (id) DO UPDATE SET
    category = EXCLUDED.category,
    question = EXCLUDED.question,
    answer = EXCLUDED.answer,
    embedding = EXCLUDED.embedding;

SELECT setval(pg_get_serial_sequence('public.qa', 'id'), COALESCE((SELECT MAX(id) FROM public.qa), 1), true);

CREATE INDEX IF NOT EXISTS qa_embedding_hnsw_idx
    ON public.qa USING hnsw (embedding vector_cosine_ops);


-- Public FAQ entries are read-only from the Streamlit app.
ALTER TABLE public.qa ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS qa_public_read ON public.qa;
CREATE POLICY qa_public_read
    ON public.qa
    FOR SELECT
    TO anon, authenticated
    USING (true);
GRANT SELECT ON TABLE public.qa TO anon, authenticated;

-- RPC performs category filtering and cosine-similarity search inside Postgres.
CREATE OR REPLACE FUNCTION public.match_qa(
    query_embedding vector(384),
    match_threshold float,
    match_count integer,
    filter_category text DEFAULT NULL
)
RETURNS TABLE (
    id bigint,
    category text,
    question text,
    answer text,
    similarity double precision
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, extensions
AS $$
    SELECT
        q.id,
        q.category,
        q.question,
        q.answer,
        (1 - (q.embedding <=> query_embedding))::double precision AS similarity
    FROM public.qa AS q
    WHERE q.embedding IS NOT NULL
      AND (filter_category IS NULL OR q.category = filter_category)
      AND (q.embedding <=> query_embedding) <= (1 - match_threshold)
    ORDER BY q.embedding <=> query_embedding ASC
    LIMIT LEAST(GREATEST(match_count, 1), 100);
$$;
GRANT EXECUTE ON FUNCTION public.match_qa(vector, float, integer, text)
    TO anon, authenticated;
